#!/usr/bin/env python3
"""
Patch 06: MapLibre GL JS basemap, framed on the case's real coordinates.

Run from the repository root AFTER `npm install maplibre-gl@6.11.2` in
frontend/. Stages everything, checks every anchor, writes nothing unless all of
it matches, and is safe to re-run.

  new:  frontend/src/BaseMap.jsx, BaseMap.css, cards/BasemapCard.jsx
  edit: frontend/src/App.jsx (mount the card), ui/glossary.js (captions), CHANGELOG.md
"""
import json, os, sys

def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")

if not (os.path.isfile("frontend/src/App.jsx") and os.path.isdir("slicktrace_core")):
    abort("run this from the slick-trace repository root")
if not os.path.isdir("frontend/src/cards"):
    abort("patch 05 (generic cards) is not applied")
try:
    v = json.load(open("frontend/node_modules/maplibre-gl/package.json"))["version"]
except OSError:
    abort("maplibre-gl is not installed: run  (cd frontend && npm install maplibre-gl@6.11.2)  first")
if v.split(".")[0] != "6":
    abort(f"maplibre-gl {v} is installed; this patch was written and tested against 6.11.2")

NEW = {'frontend/src/BaseMap.jsx': 'import { useEffect, useRef, useState } from \'react\';\nimport {\n  AttributionControl, Map as MapLibreMap, NavigationControl, ScaleControl, setWorkerUrl,\n} from \'maplibre-gl\';\nimport \'maplibre-gl/dist/maplibre-gl.css\';\n// MapLibre 6 computes its worker\'s URL at run time, which a bundler cannot\n// see, so the worker was never emitted and GeoJSON layers failed to load.\n// Vite bundles it here (with the chunk it imports) and hands back its URL.\nimport workerUrl from \'maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url\';\nimport \'./BaseMap.css\';\n\n/**\n * Basemap for one case, framed on the scene\'s real coordinates.\n *\n * Two modes, chosen at run time rather than build time:\n *   imagery  Esri World Imagery through an ArcGIS Location Platform key read\n *            from VITE_ARCGIS_API_KEY (frontend/.env.local, never committed).\n *   offline  a plain sea background with the real coastline from this app\'s\n *            own /api/geo/coastline, so the map frames correctly with no key\n *            and no network.\n * If imagery was requested but its tiles fail (key rejected, referrer not\n * allowed, offline), the imagery layer is hidden and the map says so, rather\n * than showing a blank or broken grid.\n *\n * Basemap only: no case data is drawn yet. The dashed rectangle is the\n * scene\'s extent (meta.bbox), shown so the framing can be checked by eye.\n */\n\nsetWorkerUrl(workerUrl);\n\nconst KEY = import.meta.env.VITE_ARCGIS_API_KEY;\nconst IMAGERY_TILES = \'https://ibasemaps-api.arcgis.com/arcgis/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}\';\nconst ESRI_ATTRIBUTION = \'Powered by <a href="https://www.esri.com" target="_blank" rel="noreferrer">Esri</a>\'\n  + \' | Esri, Maxar, Earthstar Geographics, and the GIS User Community\';\n\n// MapLibre paints with concrete colours, so the two themes are spelled out\n// here rather than read from CSS variables.\nconst PALETTE = {\n  light: { sea: \'#dfe9f1\', coast: \'rgba(0,0,0,0.55)\', frame: \'#007aff\' },\n  dark: { sea: \'#15202b\', coast: \'rgba(255,255,255,0.6)\', frame: \'#0a84ff\' },\n};\n\nfunction currentTheme() {\n  const forced = document.documentElement.dataset.theme;\n  if (forced === \'light\' || forced === \'dark\') return forced;\n  return window.matchMedia(\'(prefers-color-scheme: dark)\').matches ? \'dark\' : \'light\';\n}\n\nfunction frameOf(b) {\n  return {\n    type: \'Feature\', properties: {},\n    geometry: {\n      type: \'LineString\',\n      coordinates: [[b.min_lon, b.min_lat], [b.max_lon, b.min_lat], [b.max_lon, b.max_lat],\n                    [b.min_lon, b.max_lat], [b.min_lon, b.min_lat]],\n    },\n  };\n}\n\nfunction styleFor(bbox, theme) {\n  const p = PALETTE[theme];\n  const sources = {\n    coast: { type: \'geojson\', data: { type: \'FeatureCollection\', features: [] } },\n    frame: { type: \'geojson\', data: frameOf(bbox) },\n  };\n  const layers = [{ id: \'sea\', type: \'background\', paint: { \'background-color\': p.sea } }];\n  if (KEY) {\n    sources.imagery = {\n      type: \'raster\', tiles: [`${IMAGERY_TILES}?token=${encodeURIComponent(KEY)}`],\n      tileSize: 256, maxzoom: 19, attribution: ESRI_ATTRIBUTION,\n    };\n    layers.push({ id: \'imagery\', type: \'raster\', source: \'imagery\' });\n  }\n  layers.push(\n    { id: \'coast\', type: \'line\', source: \'coast\', paint: { \'line-color\': p.coast, \'line-width\': 1.1 } },\n    { id: \'frame\', type: \'line\', source: \'frame\',\n      paint: { \'line-color\': p.frame, \'line-width\': 1.5, \'line-dasharray\': [3, 2] } },\n  );\n  return { version: 8, sources, layers };\n}\n\nexport default function BaseMap({ bbox, api, onMode }) {\n  const el = useRef(null);\n  const mapRef = useRef(null);\n  const [mode, setMode] = useState(KEY ? \'imagery\' : \'offline\');\n\n  useEffect(() => { onMode?.(mode); }, [mode, onMode]);\n\n  useEffect(() => {\n    if (!el.current || !bbox) return undefined;\n    const bounds = [[bbox.min_lon, bbox.min_lat], [bbox.max_lon, bbox.max_lat]];\n    const map = new MapLibreMap({\n      container: el.current,\n      style: styleFor(bbox, currentTheme()),\n      bounds,\n      fitBoundsOptions: { padding: 24 },\n      attributionControl: false,\n      dragRotate: false,\n      pitchWithRotate: false,\n    });\n    mapRef.current = map;\n    map.touchZoomRotate.disableRotation();\n    map.addControl(new NavigationControl({ showCompass: false }), \'top-right\');\n    map.addControl(new ScaleControl({ unit: \'metric\' }), \'bottom-left\');\n    map.addControl(new AttributionControl({ compact: true }), \'bottom-right\');\n\n    // one failed imagery tile before any has loaded means the key or network is\n    // the problem, not one missing tile: fall back instead of showing holes\n    let imageryLoaded = false;\n    map.on(\'sourcedata\', (e) => {\n      if (e.sourceId === \'imagery\' && e.tile && e.tile.state === \'loaded\') imageryLoaded = true;\n    });\n    map.on(\'error\', (e) => {\n      if (KEY && !imageryLoaded && e.sourceId === \'imagery\' && map.getLayer(\'imagery\')) {\n        map.setLayoutProperty(\'imagery\', \'visibility\', \'none\');\n        setMode(\'imagery-failed\');\n      }\n    });\n\n    let alive = true;\n    api.realCoastline()\n      .then((r) => {\n        if (!alive) return;\n        const set = () => map.getSource(\'coast\')?.setData({ type: \'Feature\', properties: {}, geometry: r.geometry });\n        if (map.isStyleLoaded()) set(); else map.once(\'load\', set);\n      })\n      .catch(() => {});\n\n    // follow the appearance control without rebuilding the map\n    const repaint = () => {\n      const p = PALETTE[currentTheme()];\n      if (!map.getLayer(\'sea\')) return;\n      map.setPaintProperty(\'sea\', \'background-color\', p.sea);\n      map.setPaintProperty(\'coast\', \'line-color\', p.coast);\n      map.setPaintProperty(\'frame\', \'line-color\', p.frame);\n    };\n    const mo = new MutationObserver(repaint);\n    mo.observe(document.documentElement, { attributes: true, attributeFilter: [\'data-theme\'] });\n    const mq = window.matchMedia(\'(prefers-color-scheme: dark)\');\n    mq.addEventListener(\'change\', repaint);\n\n    return () => {\n      alive = false;\n      mo.disconnect();\n      mq.removeEventListener(\'change\', repaint);\n      map.remove();\n      mapRef.current = null;\n    };\n  }, [bbox, api]);\n\n  return (\n    <div className="basemap">\n      <div ref={el} className="basemap-canvas" role="img"\n           aria-label={`Map of the scene extent, ${bbox.min_lon}–${bbox.max_lon}° E, ${bbox.min_lat}–${bbox.max_lat}° N`} />\n      <div className="basemap-label">\n        {mode === \'imagery\' && \'Real satellite imagery · case data is synthetic\'}\n        {mode === \'offline\' && \'Offline basemap: real coastline only · add an Esri key for imagery\'}\n        {mode === \'imagery-failed\' && \'Imagery unavailable (key rejected or offline) · showing real coastline\'}\n      </div>\n    </div>\n  );\n}\n', 'frontend/src/BaseMap.css': "/* Basemap: a fixed-height canvas with a label that always says what is shown. */\n\n.basemap {\n  position: relative;\n  height: 440px;\n  border-radius: var(--radius-lg);\n  overflow: hidden;\n  box-shadow: 0 0 0 0.5px var(--separator-strong);\n  background: var(--surface-sunken);\n}\n\n.basemap-canvas {\n  position: absolute;\n  inset: 0;\n}\n\n.basemap-label {\n  position: absolute;\n  top: 10px;\n  left: 10px;\n  max-width: calc(100% - 80px);\n  padding: 5px 9px;\n  border-radius: 7px;\n  background: var(--material-header);\n  -webkit-backdrop-filter: var(--blur-material);\n  backdrop-filter: var(--blur-material);\n  box-shadow: var(--shadow-control);\n  color: var(--label-1);\n  font-size: var(--font-size-xs);\n  font-weight: var(--font-weight-medium);\n  pointer-events: none;\n}\n\n/* MapLibre's controls, restyled to the design system */\n.basemap .maplibregl-ctrl-group {\n  border-radius: 7px;\n  background: var(--control-bg);\n  box-shadow: var(--shadow-control);\n}\n\n.basemap .maplibregl-ctrl-group button + button {\n  border-top: 1px solid var(--separator);\n}\n\n.basemap .maplibregl-ctrl-attrib {\n  font-size: 10px;\n}\n\n@media (max-width: 620px) {\n  .basemap { height: 320px; }\n}\n\n.basemap-loading {\n  display: grid;\n  place-items: center;\n  color: var(--label-2);\n  font-size: var(--font-size-sm);\n}\n", 'frontend/src/cards/BasemapCard.jsx': 'import { lazy, Suspense } from \'react\';\nimport { Badge, Card } from \'../ui/primitives\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n// MapLibre is about a megabyte: load it in its own chunk, only when this card\n// renders, so the rest of the page never waits for it.\nconst BaseMap = lazy(() => import(\'../BaseMap\'));\n\n/**\n * Basemap preview for the selected case: the scene\'s extent on a real map,\n * before any case data is drawn on it (that arrives layer by layer in Phase 4).\n */\nexport default function BasemapCard({ meta, api }) {\n  if (!meta) return null;\n  return (\n    <Card title="Scene Map" badge={<Badge>basemap preview</Badge>} caption={C.basemap}\n          footnote={`Scene extent (dashed): ${meta.bbox.min_lon}–${meta.bbox.max_lon}° E, `\n            + `${meta.bbox.min_lat}–${meta.bbox.max_lat}° N, ${meta.crs}. ${C.basemapGeography}`}>\n      <Suspense fallback={<div className="basemap basemap-loading">Loading map…</div>}>\n        <BaseMap bbox={meta.bbox} api={api} />\n      </Suspense>\n    </Card>\n  );\n}\n'}
EDITS = [('frontend/src/App.jsx', "import HistoricalReplayCard from './cards/HistoricalReplayCard';\n", "import HistoricalReplayCard from './cards/HistoricalReplayCard';\nimport BasemapCard from './cards/BasemapCard';\n"), ('frontend/src/App.jsx', '                <HistoricalReplayCard incidentId={incidentId} api={api} tracks={tracks}\n', '                <BasemapCard meta={meta} api={api} />\n                <HistoricalReplayCard incidentId={incidentId} api={api} tracks={tracks}\n'), ('frontend/src/ui/glossary.js', '  // ask\n', "  // basemap\n  basemap: 'The real map under this case: satellite imagery when an Esri key is set, otherwise the '\n    + 'real coastline on a plain sea. Nothing from the case is drawn on it yet.',\n  basemapGeography: 'The case’s own coastline and sensitive areas are synthetic and do not follow the '\n    + 'real coast, so later overlays are drawn against both.',\n\n  // ask\n"), ('CHANGELOG.md', 'replaced by native bars (bundle 619 KB to 271 KB).\n', "replaced by native bars (bundle 619 KB to 271 KB).\n\n**Scene map: MapLibre GL JS basemap, framed on real coordinates.** A Scene Map\ncard shows the selected case's extent (`meta.bbox`, EPSG:4326) on Esri World\nImagery when `VITE_ARCGIS_API_KEY` is set in `frontend/.env.local` (gitignored),\nand on the real coastline over a plain sea when it is not. If imagery tiles fail\n(key rejected, referrer not allowed, offline) the map falls back and says so.\nBasemap only: no case data is drawn on it yet. Esri attribution is shown as its\nterms require.\n")]

writes, skipped = {}, 0
read = lambda p: open(p, encoding="utf-8").read()
for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text:
            skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text
for p, old, new in EDITS:
    t = writes.get(p) or read(p)
    if new in t:
        skipped += 1; continue
    if t.count(old) != 1:
        abort(f"{p}: anchor {old.strip().splitlines()[0][:60]!r} matched {t.count(old)} times")
    writes[p] = t.replace(old, new, 1)

for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 06: {len(writes)} files written, {skipped} already in place.")
